import java.util.Scanner;

public class Main {
    static long target;
    static int answer = Integer.MAX_VALUE;

    static void explore(long current, int steps) {
        if (steps >= answer) return;
        if (current == 0) {
            answer = steps;
            return;
        }
        long power = 1;
        int multiplier = 1;
        while (power * 10 + 1 <= current) {
            power = power * 10 + 1;
            multiplier++;
        }
        explore(current % power, steps + multiplier * (int)(current / power));
        explore(power * 10 + 1 - current, steps + 1 + multiplier);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        target = scanner.nextLong();
        explore(target, 0);
        System.out.println(answer);
        scanner.close();
    }
}
